from IQCommon.data.pandas import pandas
import requests
ParserError = pandas.errors.ParserError
EmptyDataError = pandas.errors.EmptyDataError
assert_frame_equal = pandas.testing.assert_frame_equal
def get_python_version():
    import traceback
    import sys
    flag = '0'
    try:
        if sys.version_info[0] == 3 and sys.version_info[1] == 5 and sys.version_info[2] == 1:
            flag = '3.5'
        elif sys.version_info[0] == 3 and sys.version_info[1] == 5 and sys.version_info[2] == 2:
            flag = '3.5'
        elif sys.version_info[0] == 3 and sys.version_info[1] == 11:
            flag = '3.11'
        else:
            print('不支持该版本: Python {:s} on {:s}'.format(sys.version, sys.platform))
    except:
        traceback.print_exc()
    else:
        return flag
    finally:
        globals()['python_version'] = flag